//! Public `sysroot catalog lock` workflows: fixed-output RPM objects, offline
//! repositories and their refusals. The default case serves generated bytes on
//! loopback; the Docker cases are opt-in because they build a signed fixture
//! repository or resolve against real Fedora mirrors.
#![cfg(unix)]

use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::net::TcpListener;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

static NEXT: AtomicU64 = AtomicU64::new(0);
const BASE: &str = "quay.io/fedora/fedora-bootc@sha256:5c83705128303c5bca5134fbdcb5ad866b6f13072ecb4174cf31a3c9e64e0c27";
const KEY: &str = "6d9f90a6";
const INSTALLER: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../usr/src/kedra/image/catalog/install-rpms.sh"
);
/// Docker Official Images' Fedora 44 index (as tests/container/lab/inputs.Containerfile).
const FEDORA: &str = "docker.io/library/fedora:44@sha256:43b29f65a41eb9c35e1cd5323e3bdf3b655c2357a9f4f1ff2f9c2798e5045d80";

struct Fixture {
    root: PathBuf,
    binary: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "kedra-rpm-lock-e2e-{}-{nonce}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&root).unwrap();
        fs::set_permissions(&root, fs::Permissions::from_mode(0o700)).unwrap();
        let binary = std::env::var_os("KEDRA_ENGINE_E2E_BINARY").map_or_else(
            || PathBuf::from(env!("CARGO_BIN_EXE_sysroot")),
            PathBuf::from,
        );
        Self { root, binary }
    }

    fn path(&self, name: &str) -> PathBuf {
        self.root.join(name)
    }

    fn lock(&self, arguments: &[&str]) -> Output {
        Command::new(&self.binary)
            .args(["catalog", "lock"])
            .args(arguments)
            .output()
            .unwrap()
    }

    fn json(&self, arguments: &[&str]) -> Value {
        serde_json::from_slice(&success(self.lock(arguments)).stdout).unwrap()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        remove_owned(&self.root);
    }
}

/// Store objects are sealed read-only; restore write permission to remove them.
fn remove_owned(path: &Path) {
    if let Ok(metadata) = fs::symlink_metadata(path)
        && metadata.is_dir()
    {
        let _ = fs::set_permissions(path, fs::Permissions::from_mode(0o700));
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                remove_owned(&entry.path());
            }
        }
        let _ = fs::remove_dir(path);
    } else {
        let _ = fs::remove_file(path);
    }
}

fn text(path: &Path) -> &str {
    path.to_str().unwrap()
}

fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn success(output: Output) -> Output {
    assert!(
        output.status.success(),
        "stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    output
}

fn denied(output: Output, diagnostic: &str) {
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(!output.status.success(), "unexpected success: {stderr}");
    assert!(
        stderr.contains(diagnostic),
        "missing {diagnostic:?} in {stderr}"
    );
}

/// Minimal HTTP/1.1 file server whose content the test can replace.
fn serve(files: Arc<Mutex<BTreeMap<String, Vec<u8>>>>) -> String {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    std::thread::spawn(move || {
        for stream in listener.incoming().flatten() {
            let mut reader = BufReader::new(stream);
            let mut request = String::new();
            if reader.read_line(&mut request).is_err() {
                continue;
            }
            let mut line = String::new();
            while reader.read_line(&mut line).is_ok_and(|n| n > 2) {
                line.clear();
            }
            let path = request.split_whitespace().nth(1).unwrap_or_default();
            let body = files.lock().unwrap().get(path).cloned();
            let mut stream = reader.into_inner();
            let _ = match body {
                Some(body) => stream
                    .write_all(
                        format!(
                            "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                            body.len()
                        )
                        .as_bytes(),
                    )
                    .and_then(|()| stream.write_all(&body)),
                None => stream.write_all(
                    b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                ),
            };
        }
    });
    format!("http://{address}")
}

struct Package {
    file: String,
    bytes: Vec<u8>,
    entry: Value,
    row: Vec<String>,
}

fn package(name: &str, version: &str, mirror: &str) -> Package {
    let file = format!("{name}-{version}-1.fc44.noarch.rpm");
    let bytes = format!("generated RPM stand-in for {file}\n")
        .repeat(512)
        .into_bytes();
    let sha256 = hash(&bytes);
    let source_rpm = format!("{name}-{version}-1.fc44.src.rpm");
    let row = vec![
        name.to_owned(),
        "0".into(),
        version.into(),
        "1.fc44".into(),
        "noarch".into(),
        hash(format!("{file} header").as_bytes()),
        hash(format!("{file} payload").as_bytes()),
    ];
    let entry = json!({
        "name": name, "epoch": "0", "version": version, "release": "1.fc44", "arch": "noarch",
        "size": bytes.len(), "sha256": sha256, "header_sha256": row[5], "payload_sha256": row[6],
        "source_rpm": source_rpm, "repository": "updates",
        "durable_url": sysroot_engine::koji_url(&source_rpm, KEY, "noarch", &file).unwrap(),
        "mirror_url": format!("{mirror}/updates/Packages/{file}"),
        "object": sysroot_engine::rpm_object(&file, bytes.len() as u64, &sha256).unwrap(),
    });
    Package {
        file,
        bytes,
        entry,
        row,
    }
}

fn generated_lock(packages: &[Package]) -> Value {
    let mut rows: Vec<Vec<String>> = packages.iter().map(|p| p.row.clone()).collect();
    rows.push(vec![
        "bash".into(),
        "0".into(),
        "5.3.0".into(),
        "2.fc44".into(),
        "aarch64".into(),
        hash(b"bash header"),
        hash(b"bash payload"),
    ]);
    rows.sort();
    let rpms: serde_json::Map<String, Value> = packages
        .iter()
        .map(|p| (p.file.clone(), p.entry.clone()))
        .collect();
    let install: Vec<&str> = packages.iter().map(|p| p.file.as_str()).collect();
    json!({
        "schema_version": 1, "format": "kedra-rpm-lock", "target": "qemu-arm64",
        "architecture": "aarch64", "fedora_release": 44, "base": BASE,
        "repositories": ["fedora", "updates"], "intent_sha256": hash(b"intent"),
        "rpms": rpms,
        "foundation": {"requests": ["kedra-fixture-app"], "remove": [], "install": install, "packages": rows},
        "builders": {},
    })
}

fn write_lock(path: &Path, lock: &Value) -> Vec<u8> {
    let bytes = serde_json::to_vec(lock).unwrap();
    fs::write(path, &bytes).unwrap();
    bytes
}

#[test]
fn fixed_output_rpms_fetch_materialize_and_refuse_other_bytes() {
    let fixture = Fixture::new();
    let files = Arc::new(Mutex::new(BTreeMap::new()));
    let mirror = serve(files.clone());
    let packages = [
        package("kedra-fixture-app", "1.0", &mirror),
        package("kedra-fixture-lib", "1.1", &mirror),
    ];
    for p in &packages {
        files
            .lock()
            .unwrap()
            .insert(format!("/updates/Packages/{}", p.file), p.bytes.clone());
    }
    let lock = generated_lock(&packages);
    let lock_path = fixture.path("rpm-lock.json");
    let lock_bytes = write_lock(&lock_path, &lock);
    let store = fixture.path("store");

    // Fetch admits each RPM as its predicted object; a second fetch reuses them.
    let fetched = fixture.json(&["fetch", "--store", text(&store), "--lock", text(&lock_path)]);
    assert_eq!(
        (fetched["fetched"].as_u64(), fetched["present"].as_u64()),
        (Some(2), Some(0))
    );
    for p in &packages {
        assert!(
            fetched["sources"][&p.file]
                .as_str()
                .unwrap()
                .starts_with(&mirror)
        );
        assert!(
            store
                .join("objects")
                .join(p.entry["object"].as_str().unwrap())
                .is_dir()
        );
    }
    let again = fixture.json(&["fetch", "--store", text(&store), "--lock", text(&lock_path)]);
    assert_eq!(
        (again["fetched"].as_u64(), again["present"].as_u64()),
        (Some(0), Some(2))
    );

    // The offline repository holds exactly the role's files and the lock bytes.
    let repository = fixture.path("repository");
    let repo = fixture.json(&[
        "repo",
        "--store",
        text(&store),
        "--lock",
        text(&lock_path),
        "--foundation",
        "--output",
        text(&repository),
    ]);
    assert_eq!(repo["rpms"].as_u64(), Some(2));
    assert_eq!(repo["pins_sha256"], fetched["pins_sha256"]);
    assert_eq!(fs::read(repository.join("lock.json")).unwrap(), lock_bytes);
    let mut names: Vec<_> = fs::read_dir(repository.join("packages"))
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect();
    names.sort();
    assert_eq!(names, [packages[0].file.clone(), packages[1].file.clone()]);
    for p in &packages {
        assert_eq!(
            fs::read(repository.join("packages").join(&p.file)).unwrap(),
            p.bytes
        );
    }
    denied(
        fixture.lock(&[
            "repo",
            "--store",
            text(&store),
            "--lock",
            text(&lock_path),
            "--foundation",
            "--output",
            text(&repository),
        ]),
        "exists",
    );

    // Mirror URLs are provenance: the pins hash ignores them.
    let mut moved = lock.clone();
    for p in &packages {
        moved["rpms"][&p.file]["mirror_url"] = json!(format!("{mirror}/mirror-b/{}", p.file));
    }
    let moved_path = fixture.path("moved-lock.json");
    write_lock(&moved_path, &moved);
    let present = fixture.json(&[
        "fetch",
        "--store",
        text(&store),
        "--lock",
        text(&moved_path),
    ]);
    assert_eq!(present["pins_sha256"], fetched["pins_sha256"]);

    // Other bytes from the mirror (and an unreachable Koji path) admit nothing.
    files.lock().unwrap().insert(
        format!("/updates/Packages/{}", packages[0].file),
        b"tampered".repeat(64),
    );
    let fresh = fixture.path("fresh-store");
    denied(
        fixture.lock(&["fetch", "--store", text(&fresh), "--lock", text(&lock_path)]),
        "differs from the lock",
    );
    assert!(
        !fresh
            .join("objects")
            .join(packages[0].entry["object"].as_str().unwrap())
            .exists()
    );

    // A lock whose object is not its fixed-output identity, or that is not
    // canonical, is refused before any store access.
    let mut forged = lock.clone();
    forged["rpms"][&packages[0].file]["object"] = packages[1].entry["object"].clone();
    let forged_path = fixture.path("forged-lock.json");
    write_lock(&forged_path, &forged);
    denied(
        fixture.lock(&[
            "fetch",
            "--store",
            text(&fresh),
            "--lock",
            text(&forged_path),
        ]),
        "fixed-output identity",
    );
    let pretty = fixture.path("pretty-lock.json");
    fs::write(&pretty, serde_json::to_vec_pretty(&lock).unwrap()).unwrap();
    denied(
        fixture.lock(&["fetch", "--store", text(&fresh), "--lock", text(&pretty)]),
        "not canonical",
    );

    // A changed store object is refused before the repository directory exists.
    let object = store
        .join("objects")
        .join(packages[1].entry["object"].as_str().unwrap())
        .join("data");
    fs::set_permissions(&object, fs::Permissions::from_mode(0o755)).unwrap();
    let stored = object.join(&packages[1].file);
    fs::set_permissions(&stored, fs::Permissions::from_mode(0o644)).unwrap();
    let mut changed = packages[1].bytes.clone();
    changed[0] ^= 1;
    fs::write(&stored, changed).unwrap();
    fs::set_permissions(&stored, fs::Permissions::from_mode(0o444)).unwrap();
    fs::set_permissions(&object, fs::Permissions::from_mode(0o555)).unwrap();
    let second = fixture.path("second-repository");
    denied(
        fixture.lock(&[
            "repo",
            "--store",
            text(&store),
            "--lock",
            text(&lock_path),
            "--foundation",
            "--output",
            text(&second),
        ]),
        "digest differs",
    );
    assert!(!second.exists());
}

/// `--label` for the containers and images a case creates, from
/// `KEDRA_TEST_DOCKER_LABEL` (`key=value`), so a runner can find and remove them.
fn labels() -> Vec<String> {
    std::env::var("KEDRA_TEST_DOCKER_LABEL")
        .ok()
        .filter(|label| !label.is_empty())
        .map(|label| vec!["--label".to_owned(), label])
        .unwrap_or_default()
}

fn docker(arguments: &[&str]) -> String {
    let mut command = Command::new("docker");
    match arguments.split_first() {
        Some((verb @ (&"run" | &"build"), rest)) => command.arg(verb).args(labels()).args(rest),
        _ => command.args(arguments),
    };
    String::from_utf8(success(command.output().unwrap()).stdout)
        .unwrap()
        .trim()
        .to_owned()
}

/// The closed release target whose architecture is the Docker engine's.
fn native_target() -> (&'static str, &'static str) {
    match docker(&["info", "--format", "{{.Architecture}}"]).as_str() {
        "aarch64" | "arm64" => ("qemu-arm64", "aarch64"),
        "x86_64" | "amd64" => ("desktop", "x86_64"),
        other => panic!("unsupported Docker architecture {other}"),
    }
}

/// Owned Docker images and containers, removed when the case ends.
struct Resources(Vec<Vec<String>>);

impl Drop for Resources {
    fn drop(&mut self) {
        for arguments in self.0.iter().rev() {
            let _ = Command::new("docker").args(arguments).output();
        }
    }
}

/// A catalog whose target selects one probe package per builder role.
fn catalog(
    fixture: &Fixture,
    target: &str,
    foundation: &str,
    builders: &[(&str, &str)],
) -> Vec<String> {
    let root = fixture.path("catalog");
    fs::create_dir(&root).unwrap();
    let mut source = format!(
        "language 1;\nnamespace \"kedra\";\nfoundation system {{ fedora = 44; {foundation} }}\n"
    );
    let mut selected = Vec::new();
    for (name, packages) in builders {
        source.push_str(&format!(
            r##"builder {name} {{ base = system; packages = [{packages}]; }}
package probe_{name}(builder: Builder, runtime: Foundation) {{
    version = "1"; summary = "RPM lock probe"; license = "MIT";
    source = files {{ "probe.txt" = text "probe\n"; }};
    build = shell """
        mkdir -p "$out/bin"
        """;
    export command "probe-{name}" = "bin/probe";
}}
"##
        ));
        selected.push(format!("probe_{name}(builder: {name}, runtime: system)"));
    }
    source.push_str(&format!(
        "target \"{target}\" {{ foundation = system; packages = [{}]; }}\n",
        selected.join(", ")
    ));
    fs::write(root.join("catalog.kedra"), source).unwrap();
    fs::write(
        root.join("packages.lock.json"),
        br#"{"schema_version":1,"sources":{}}"#,
    )
    .unwrap();
    let policy = fixture.path("package-policy.json");
    fs::write(
        &policy,
        serde_json::to_vec(&json!({"schema_version":1,"namespace":"kedra","targets":[target],"repositories":["fedora","updates"],"required_packages":[]})).unwrap(),
    )
    .unwrap();
    [
        "--input-root",
        text(&root),
        "--entry",
        "catalog.kedra",
        "--lock",
        "packages.lock.json",
        "--target",
        target,
        "--target-policy",
        text(&policy),
    ]
    .map(String::from)
    .to_vec()
}

/// Resolve into `store`; the lock and logs are named after the store.
fn resolve(fixture: &Fixture, inputs: &[String], base: &str, store: &Path) -> (Value, PathBuf) {
    let output = store.with_extension("rpm-lock.json");
    let logs = store.with_extension("resolver-logs");
    let mut arguments: Vec<&str> = vec!["resolve"];
    arguments.extend(inputs.iter().map(String::as_str));
    arguments.extend([
        "--base",
        base,
        "--store",
        text(store),
        "--log-dir",
        text(&logs),
        "--output",
        text(&output),
    ]);
    let summary = fixture.json(&arguments);
    assert_eq!(summary["lock"].as_str(), Some(text(&output)));
    (
        serde_json::from_slice(&fs::read(&output).unwrap()).unwrap(),
        output,
    )
}

/// Build `parent` plus one offline role install; `network none` proves no fetch.
fn offline_build(
    fixture: &Fixture,
    name: &str,
    parent: &str,
    role: &[&str],
    repository: &Path,
) -> Output {
    let context = fixture.path(name);
    fs::create_dir(&context).unwrap();
    fs::copy(INSTALLER, context.join("install-rpms.sh")).unwrap();
    fs::rename(repository, context.join("rpms")).unwrap();
    let mut steps = vec![
        "/bin/bash".to_owned(),
        "/tmp/kedra-install-rpms.sh".into(),
        "/run/kedra-rpms".into(),
    ];
    steps.extend(role.iter().map(|part| format!("'{part}'")));
    fs::write(
        context.join("Containerfile"),
        format!(
            "FROM {parent}\nCOPY install-rpms.sh /tmp/kedra-install-rpms.sh\n\
             RUN --network=none --mount=type=bind,source=rpms,target=/run/kedra-rpms,ro \
             {} && install -D -m 0644 /run/kedra-rpms/lock.json /usr/share/sysroot/rpm-lock.json\n",
            steps.join(" ")
        ),
    )
    .unwrap();
    Command::new("docker")
        .arg("build")
        .args(labels())
        .args(["--pull=false", "--network", "none", "--iidfile"])
        .arg(context.join("image.iid"))
        .args(["--file"])
        .arg(context.join("Containerfile"))
        .arg(&context)
        .output()
        .unwrap()
}

fn installed_rows(image: &str) -> Vec<Vec<String>> {
    let listing = docker(&[
        "run",
        "--rm",
        "--network",
        "none",
        "--entrypoint",
        "/usr/bin/rpm",
        image,
        "-qa",
        "--qf",
        "%{NAME}\t%{EPOCHNUM}\t%{VERSION}\t%{RELEASE}\t%{ARCH}\t%{SHA256HEADER}\t%{PAYLOADSHA256}\n",
    ]);
    let mut rows: Vec<Vec<String>> = listing
        .lines()
        .filter(|line| !line.starts_with("gpg-pubkey\t"))
        .map(|line| line.split('\t').map(String::from).collect())
        .collect();
    rows.sort();
    rows
}

fn rows(value: &Value) -> Vec<Vec<String>> {
    serde_json::from_value(value.clone()).unwrap()
}

fn names(value: &Value) -> Vec<String> {
    serde_json::from_value(value.clone()).unwrap()
}

